mapper.select:
SELECT b.id, b.factory_id, b.cutting_plan_id, b.order_id, o.order_no, o.style_id, s.style_code, s.style_name, b.color, b.size, b.fabric, b.part, cp.bed_no, b.bundle_no, b.global_bundle_no, b.qty, b.status, b.created_at FROM bundle b LEFT JOIN `order` o ON b.order_id = o.id AND o.deleted = 0 LEFT JOIN style s ON o.style_id = s.id AND s.deleted = 0 LEFT JOIN cutting_plan cp ON b.cutting_plan_id = cp.id AND cp.deleted = 0 WHERE b.factory_id = #{factoryId}
AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND s.style_code LIKE CONCAT('%', #{styleCode}, '%')
AND b.color = #{color}
AND b.size = #{size}
AND b.status = #{status}
ORDER BY b.created_at DESC
